package org.apache.commons.codec.language;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringEncoder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DoubleMetaphone_isDoubleMetaphoneEqual_TriageGen0Test {

    private DoubleMetaphone doubleMetaphone;

    @Before
    public void setUp() {
        doubleMetaphone = new DoubleMetaphone();
    }

    @Test
    public void testIsDoubleMetaphoneEqual_SameStrings_AlternateFalse() {
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual("Smith", "Smith", false));
    }

    @Test
    public void testIsDoubleMetaphoneEqual_PhoneticMatch_AlternateFalse() {
        // "Smith" and "Schmidt" often result in the same metaphone code
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual("Smith", "Schmidt", false));
    }

    @Test
    public void testIsDoubleMetaphoneEqual_DifferentStrings_AlternateFalse() {
        assertFalse(doubleMetaphone.isDoubleMetaphoneEqual("Apple", "Banana", false));
    }

    @Test
    public void testIsDoubleMetaphoneEqual_SameStrings_AlternateTrue() {
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual("Smith", "Smith", true));
    }

    @Test
    public void testIsDoubleMetaphoneEqual_PhoneticMatch_AlternateTrue() {
        // Testing that the alternate flag is actually passed through and used
        // Some words might result in different codes when alternate is true
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual("Robert", "Rupert", true));
    }

    @Test
    public void testIsDoubleMetaphoneEqual_DifferentResultsWithAlternate() {
        // Test a case where alternate flag might change equality logic
        // Note: Exact strings depend on internal DoubleMetaphone implementation,
        // but we test the branch coverage by toggling the boolean.
        String v1 = "Example";
        String v2 = "Example";
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual(v1, v2, true));
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual(v1, v2, false));
    }

    @Test(expected = NullPointerException.class)
    public void testIsDoubleMetaphoneEqual_NullValue1() {
        doubleMetaphone.isDoubleMetaphoneEqual(null, "test", false);
    }

    @Test(expected = NullPointerException.class)
    public void testIsDoubleMetaphoneEqual_NullValue2() {
        doubleMetaphone.isDoubleMetaphoneEqual("test", null, false);
    }

    @Test
    public void testIsDoubleMetaphoneEqual_EmptyStrings() {
        assertTrue(doubleMetaphone.isDoubleMetaphoneEqual("", "", false));
    }
}
